import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []

    n = len(adj)

    # Detect adjacency matrix vs adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and degree list
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj

    deg = [len(adj_list[i]) for i in range(n)]

    # Trivial cases
    if n == 1:
        return [0]
    if all(d == 0 for d in deg):
        return [0] * n
    if all(d == n - 1 for d in deg):
        return list(range(n))

    # DSATUR implementation
    colors = [-1] * n
    saturated = [set() for _ in range(n)]
    uncolored = set(range(n))

    # Helper to get degree in uncolored subgraph
    def uncolored_degree(v):
        return sum(1 for u in adj_list[v] if u in uncolored)

    # Main DSATUR loop
    while uncolored:
        # Select vertex with max saturation degree, tie-break by uncolored degree, then random
        v = max(uncolored, key=lambda x: (len(saturated[x]), uncolored_degree(x), random.random()))

        # Find smallest available color
        used = saturated[v]
        c = 0
        while c in used:
            c += 1
        colors[v] = c
        uncolored.remove(v)

        # Update saturation sets of uncolored neighbors
        for u in adj_list[v]:
            if u in uncolored:
                saturated[u].add(c)

    # Try to reduce number of colors using Kempe chain swaps
    max_color = max(colors) if n > 0 else -1
    if max_color >= 0:
        # Try to eliminate colors from highest to lowest
        for target_color in range(max_color, 0, -1):
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if colors[v] == target_color]
            if not target_vertices:
                continue

            # Try to recolor each target vertex
            eliminated = True
            for v in target_vertices:
                # Check if v can take any lower color directly
                neighbor_colors = set(colors[u] for u in adj_list[v])
                found = False
                for c in range(target_color):
                    if c not in neighbor_colors:
                        colors[v] = c
                        found = True
                        break
                if found:
                    continue

                # Try Kempe chains with each lower color
                kempe_found = False
                for c in range(target_color):
                    # Find the Kempe chain component containing v for colors (target_color, c)
                    stack = [v]
                    visited = set([v])
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for u in adj_list[node]:
                            if colors[u] == target_color or colors[u] == c:
                                if u not in visited:
                                    visited.add(u)
                                    stack.append(u)

                    # Check if we can swap: no neighbor of component has color c (outside component)
                    can_swap = True
                    for node in component:
                        for u in adj_list[node]:
                            if u not in component and colors[u] == c:
                                can_swap = False
                                break
                        if not can_swap:
                            break

                    if can_swap:
                        # Perform swap: target_color <-> c in component
                        for node in component:
                            if colors[node] == target_color:
                                colors[node] = c
                            elif colors[node] == c:
                                colors[node] = target_color
                        kempe_found = True
                        break

                if not kempe_found:
                    eliminated = False
                    break

            if eliminated:
                # Successfully eliminated target_color, reduce max_color and retry same level
                max_color -= 1
                # Restart elimination attempt for the new max_color (which is now target_color-1)
                # but we continue the loop; the next iteration will handle target_color-1
            else:
                # Could not eliminate this color, move to next lower color
                break

    return colors

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or list
    is_matrix = False
    if len(adj[0]) == n:
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor sets for efficient access
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            for v in adj[i]:
                if 0 <= v < n:
                    neighbors[i].add(v)

    # If no edges, all vertices can be color 0
    if all(len(neighbors[i]) == 0 for i in range(n)):
        return [0] * n

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: DSATUR algorithm
    def dsatur():
        color = [-1] * n
        saturation = [0] * n  # number of distinct colors in neighbors
        colored_neighbors = [set() for _ in range(n)]  # set of colors used by neighbors
        uncolored = set(range(n))

        # Initial vertex: highest degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(neighbors[x]))
            color[v] = 0
            uncolored.remove(v)
            for u in neighbors[v]:
                if 0 not in colored_neighbors[u]:
                    colored_neighbors[u].add(0)
                    saturation[u] += 1

        while uncolored:
            # Select vertex with max saturation, break ties by degree in uncolored subgraph, then random
            max_sat = -1
            candidates = []
            for v in uncolored:
                sat_v = saturation[v]
                if sat_v > max_sat:
                    max_sat = sat_v
                    candidates = [v]
                elif sat_v == max_sat:
                    candidates.append(v)
            if max_sat == -1:  # all saturation 0, pick max degree in uncolored
                v = max(uncolored, key=lambda x: len(neighbors[x] & uncolored))
            else:
                # break tie by degree in uncolored subgraph
                max_deg = -1
                tie_candidates = []
                for v in candidates:
                    deg = len(neighbors[v] & uncolored)
                    if deg > max_deg:
                        max_deg = deg
                        tie_candidates = [v]
                    elif deg == max_deg:
                        tie_candidates.append(v)
                v = random.choice(tie_candidates) if tie_candidates else random.choice(candidates)

            # Assign smallest available color
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation for uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    if c not in colored_neighbors[u]:
                        colored_neighbors[u].add(c)
                        saturation[u] += 1
        return color

    # Helper: RLF (Recursive Largest First) algorithm
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len(neighbors[x] & uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = uncolored - {v} - (neighbors[v] & uncolored)
            W = neighbors[v] & uncolored
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = n
                for u in U:
                    w_neighbors = len(neighbors[u] & W)
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        best_u = u
                        min_deg_in_U = len(neighbors[u] & U)
                    elif w_neighbors == max_w_neighbors:
                        deg_in_U = len(neighbors[u] & U)
                        if deg_in_U < min_deg_in_U:
                            min_deg_in_U = deg_in_U
                            best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                nbrs_u = neighbors[u] & U
                U -= nbrs_u
                W |= nbrs_u
            # Assign color c to all in independent_set
            for v in independent_set:
                color[v] = c
            uncolored -= independent_set
            c += 1
        return color

    # Helper: degeneracy ordering (smallest-last) and greedy coloring
    def degeneracy_order():
        # Compute degeneracy ordering (smallest-last)
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        # Bucket sort for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            if degree[v] < len(buckets):
                buckets[degree[v]].add(v)
        # Peeling
        for _ in range(n):
            # Find non-empty bucket with smallest degree
            d = 0
            while d < len(buckets) and not buckets[d]:
                d += 1
            if d >= len(buckets):
                break  # should not happen
            v = buckets[d].pop()
            order.append(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    old_deg = degree[u]
                    degree[u] -= 1
                    if old_deg < len(buckets):
                        buckets[old_deg].discard(u)
                    if degree[u] < len(buckets):
                        buckets[degree[u]].add(u)
            remaining.remove(v)
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: Kempe chain refinement to reduce colors
    def kempe_refine(color):
        # Determine current number of colors
        max_color = max(color) if n > 0 else -1
        if max_color < 0:
            return color
        # Try to eliminate color classes from highest downward
        for target_color in range(max_color, 0, -1):
            # Collect vertices with target_color
            target_vertices = [v for v in range(n) if color[v] == target_color]
            if not target_vertices:
                continue  # already eliminated
            # Try to recolor each target vertex
            eliminated = True
            for v in target_vertices:
                # Try to find a free color < target_color
                used = [False] * (target_color + 1)  # we only need up to target_color
                for u in neighbors[v]:
                    if color[u] != -1 and color[u] <= target_color:
                        used[color[u]] = True
                free_color = -1
                for c in range(target_color):
                    if not used[c]:
                        free_color = c
                        break
                if free_color != -1:
                    color[v] = free_color
                else:
                    # Try Kempe chains with each color c < target_color
                    found = False
                    for c in range(target_color):
                        # Check if v is in a component that does not contain any vertex of color c
                        # We'll do BFS/DFS on the (target_color, c) Kempe chain containing v
                        stack = [v]
                        visited = set()
                        component = set()
                        has_c = False  # whether component has a vertex of color c
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            component.add(node)
                            if color[node] == c:
                                has_c = True
                            # Explore neighbors with color target_color or c
                            for nb in neighbors[node]:
                                if color[nb] == target_color or color[nb] == c:
                                    if nb not in visited:
                                        stack.append(nb)
                        if not has_c:
                            # Swap colors target_color and c in this component
                            for node in component:
                                if color[node] == target_color:
                                    color[node] = c
                                elif color[node] == c:
                                    color[node] = target_color
                            found = True
                            break
                    if found:
                        color[v] = c  # after swap, v now has color c (since it was target_color and swapped)
                    else:
                        eliminated = False
                        break
            if not eliminated:
                # Cannot eliminate this color, break and try lower
                break
            # else, we eliminated target_color, continue to next lower
        return color

    # Try multiple algorithms and pick the best (fewest colors)
    algorithms = [
        ("greedy_degree", lambda: greedy_color(sorted(range(n), key=lambda x: -len(neighbors[x])))),
        ("dsatur", dsatur),
        ("rlf", rlf),
        ("degeneracy", degeneracy_order),
    ]
    best_color = None
    best_num_colors = float('inf')
    for name, algo in algorithms:
        try:
            col = algo()
            num_colors = max(col) + 1 if n > 0 else 0
            # Validate coloring
            valid = True
            for u in range(n):
                for v in neighbors[u]:
                    if color[u] == color[v]:
                        valid = False
                        break
                if not valid:
                    break
            if valid and num_colors < best_num_colors:
                best_num_colors = num_colors
                best_color = col[:]
        except Exception:
            continue

    # Fallback: if none worked, use greedy by degree
    if best_color is None:
        best_color = greedy_color(sorted(range(n), key=lambda x: -len(neighbors[x])))

    # Apply Kempe refinement to try to reduce colors further
    refined = kempe_refine(best_color)
    num_colors_refined = max(refined) + 1 if n > 0 else 0
    if num_colors_refined < best_num_colors:
        # Validate refined
        valid = True
        for u in range(n):
            for v in neighbors[u]:
                if refined[u] == refined[v]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            best_color = refined

    return best_color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []

    n = len(adj)

    # Detect if input is adjacency matrix (square and binary)
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        all_binary = True
        for i in range(n):
            if not all_binary:
                break
            row = adj[i]
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
        if all_binary:
            is_matrix = True

    # Build adjacency list and degree array
    if is_matrix:
        neighbors = []
        deg = [0] * n
        for i in range(n):
            row_neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    row_neighbors.append(j)
                    deg[i] += 1
            neighbors.append(row_neighbors)
    else:
        neighbors = []
        deg = [0] * n
        for i in range(n):
            # Ensure we have a list; if not, treat as empty
            if isinstance(adj[i], list):
                nbrs = adj[i]
            else:
                nbrs = []
            # Filter out self-loops and invalid indices, and deduplicate
            valid_nbrs = []
            seen = set()
            for v in nbrs:
                if isinstance(v, int) and 0 <= v < n and v != i:
                    if v not in seen:
                        seen.add(v)
                        valid_nbrs.append(v)
            neighbors.append(valid_nbrs)
            deg[i] = len(valid_nbrs)

    # Trivial cases
    if n == 1:
        return [0]
    if all(d == 0 for d in deg):
        return [0] * n

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n  # n is safe upper bound
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used[c] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: compute number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if u < v:  # check each edge once
                    if cu == coloring[v]:
                        return False
        return True

    # Strategy 1: DSATUR
    def dsatur():
        color = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        sat = [0] * n
        # colored neighbor count per color? we'll compute sat on the fly
        uncolored = set(range(n))
        # We'll maintain for each uncolored vertex, the set of colors in its colored neighbors
        # Instead, we can compute sat by checking neighbors each time (O(n) per vertex, total O(n^2))
        # Since n<=100, it's acceptable.
        while uncolored:
            # Select vertex with max sat, break ties by degree in uncolored subgraph, then random
            v = -1
            max_sat = -1
            max_deg_uncolored = -1
            for u in uncolored:
                # compute saturation degree for u
                neighbor_colors = set()
                for w in neighbors[u]:
                    if color[w] != -1:
                        neighbor_colors.add(color[w])
                sat_u = len(neighbor_colors)
                # degree in uncolored subgraph
                deg_uncolored = 0
                for w in neighbors[u]:
                    if w in uncolored:
                        deg_uncolored += 1
                # compare
                if sat_u > max_sat or (sat_u == max_sat and deg_uncolored > max_deg_uncolored) or \
                   (sat_u == max_sat and deg_uncolored == max_deg_uncolored and random.random() < 0.5):
                    max_sat = sat_u
                    max_deg_uncolored = deg_uncolored
                    v = u
            # Assign smallest available color
            used = [False] * n
            for w in neighbors[v]:
                c = color[w]
                if c != -1:
                    used[c] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Step 1: choose vertex with max degree in G[uncolored]
            v = -1
            max_deg = -1
            for u in uncolored:
                deg_uncolored = 0
                for w in neighbors[u]:
                    if w in uncolored:
                        deg_uncolored += 1
                if deg_uncolored > max_deg:
                    max_deg = deg_uncolored
                    v = u
            if v == -1:  # should not happen if uncolored non-empty
                break
            S = [v]
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                adjacent_to_S = False
                for w in S:
                    if u in neighbors[w]:
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.add(u)
                else:
                    U.add(u)
            # While U not empty
            while U:
                # select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                u_star = -1
                max_nW = -1
                min_deg_U = float('inf')
                for u in U:
                    # count neighbors in W
                    nW = 0
                    for w in neighbors[u]:
                        if w in W:
                            nW += 1
                    # degree in G[U]
                    deg_U = 0
                    for w in neighbors[u]:
                        if w in U:
                            deg_U += 1
                    if nW > max_nW or (nW == max_nW and deg_U < min_deg_U):
                        max_nW = nW
                        min_deg_U = deg_U
                        u_star = u
                if u_star == -1:
                    break  # should not happen
                S.append(u_star)
                U.remove(u_star)
                # move neighbors of u_star that are in U to W
                for w in neighbors[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for u in S:
                color[u] = c
                uncolored.remove(u)
            c += 1
        return color

    # Strategy 3: Welsh-Powell (sort by degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: deg[x], reverse=True)
        return greedy_color(order)

    # Strategy 4: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute core numbers and removal order
        # We'll simulate peeling: repeatedly remove min degree vertex
        # Use bucket sort for efficiency (n<=100, so simple)
        deg_copy = deg[:]  # current degree in remaining graph
        # adjacency sets for quick lookup
        adj_set = [set(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []  # removal order (will color in reverse)
        # We'll maintain list of vertices by current degree
        # Since n small, we can just scan
        for _ in range(n):
            # find unremoved vertex with min deg_copy
            v = -1
            min_d = float('inf')
            for u in range(n):
                if not removed[u] and deg_copy[u] < min_d:
                    min_d = deg_copy[u]
                    v = u
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            # decrease degree of neighbors
            for u in adj_set[v]:
                if not removed[u]:
                    deg_copy[u] -= 1
        # color in reverse removal order
        return greedy_color(order[::-1])

    # Strategy 5: BFS ordering
    def bfs_ordering():
        visited = [False] * n
        order = []
        for start in range(n):
            if not visited[start]:
                queue = [start]
                visited[start] = True
                while queue:
                    v = queue.pop(0)
                    order.append(v)
                    for u in neighbors[v]:
                        if not visited[u]:
                            visited[u] = True
                            queue.append(u)
        return greedy_color(order)

    # Strategy 6: Randomized greedy (multiple trials)
    def random_greedy(trials=20):
        best_coloring = None
        best_num = float('inf')
        for _ in range(trials):
            order = list(range(n))
            random.shuffle(order)
            coloring = greedy_color(order)
            if is_valid(coloring):
                num = num_colors(coloring)
                if num < best_num:
                    best_num = num
                    best_coloring = coloring[:]
        return best_coloring if best_coloring is not None else greedy_color(list(range(n)))

    # Collect candidate colorings
    candidates = []

    # Add DSATUR
    try:
        col_dsatur = dsatur()
        if is_valid(col_dsatur):
            candidates.append((num_colors(col_dsatur), col_dsatur))
    except:
        pass

    # Add RLF
    try:
        col_rlf = rlf()
        if is_valid(col_rlf):
            candidates.append((num_colors(col_rlf), col_rlf))
    except:
        pass

    # Add Welsh-Powell
    try:
        col_wp = welsh_powell()
        if is_valid(col_wp):
            candidates.append((num_colors(col_wp), col_wp))
    except:
        pass

    # Add Smallest-Last
    try:
        col_sl = smallest_last()
        if is_valid(col_sl):
            candidates.append((num_colors(col_sl), col_sl))
    except:
        pass

    # Add BFS ordering
    try:
        col_bfs = bfs_ordering()
        if is_valid(col_bfs):
            candidates.append((num_colors(col_bfs), col_bfs))
    except:
        pass

    # Add Randomized greedy
    try:
        col_rand = random_greedy(trials=15)
        if is_valid(col_rand):
            candidates.append((num_colors(col_rand), col_rand))
    except:
        pass

    # If no candidates (shouldn't happen), fallback to trivial
    if not candidates:
        # greedy in natural order
        col = greedy_color(list(range(n)))
        if is_valid(col):
            return col
        # last resort: assign each vertex a unique color
        return list(range(n))

    # Select the candidate with fewest colors
    candidates.sort(key=lambda x: x[0])
    best_coloring = candidates[0][1]

    # Optional: try to reduce colors via Kempe chains (limited to avoid timeout)
    # We'll attempt to eliminate the last color class if possible
    def kempe_reduce(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color k-1
        target_color = k - 1
        # Get vertices with target color
        target_vertices = [v for v in range(n) if coloring[v] == target_color]
        # For each vertex in target_vertices, try to recolor to a lower color
        # We'll try to move each vertex independently if possible
        new_coloring = coloring[:]  # work on copy
        for v in target_vertices:
            # Try direct reassignment to a lower color
            used = [False] * k  # we only need up to k-1
            for u in neighbors[v]:
                c = new_coloring[u]
                if c != -1 and c < k:
                    used[c] = True
            # Find smallest color < k not used
            for c in range(k):
                if not used[c]:
                    new_coloring[v] = c
                    break
            else:
                # Direct move not possible, try Kempe chains
                # For each lower color c, check if v is not connected to that color via Kempe chain
                moved = False
                for c in range(target_color):
                    # Check if v is adjacent to any vertex of color c
                    adjacent_to_c = False
                    for u in neighbors[v]:
                        if new_coloring[u] == c:
                            adjacent_to_c = True
                            break
                    if not adjacent_to_c:
                        # We can recolor v to c directly? Actually, if not adjacent, then yes.
                        # But we already checked in direct reassignment? 
                        # The used array would have shown c as free if no neighbor has color c.
                        # So if we are here, it means all lower colors are used by neighbors.
                        # So we need Kempe chain: try to swap colors c and target_color in the component
                        # containing v in the subgraph induced by colors c and target_color.
                        # Build the component of v in (c, target_color)
                        from collections import deque
                        comp = set()
                        queue = deque([v])
                        comp.add(v)
                        while queue:
                            x = queue.popleft()
                            for y in neighbors[x]:
                                if new_coloring[y] == c or new_coloring[y] == target_color:
                                    if y not in comp:
                                        comp.add(y)
                                        queue.append(y)
                        # Check if any neighbor of v in the component has color c? 
                        # Actually, we want to see if swapping the component would cause conflict.
                        # After swap, v would become color c. We need to ensure no neighbor of v has color c after swap.
                        # Neighbors of v that are in the component: if they have color c, they become target_color -> not c.
                        # Neighbors of v that are in the component and have target_color: they become c -> conflict if adjacent to v.
                        # So we need to check: for any neighbor u of v, if u is in the component and has color c, then after swap u becomes target_color -> safe.
                        # If u is in the component and has color target_color, after swap becomes c -> conflict if u is neighbor of v.
                        # Actually, if u is neighbor of v and in the component, then its color is either c or target_color.
                        # If it is c, after swap becomes target_color -> not c -> safe.
                        # If it is target_color, after swap becomes c -> then we have two adjacent vertices (v and u) both color c -> conflict.
                        # Therefore, we can only perform the swap if no neighbor of v in the component has color target_color.
                        safe = True
                        for u in neighbors[v]:
                            if u in comp and new_coloring[u] == target_color:
                                safe = False
                                break
                        if safe:
                            # perform swap
                            for x in comp:
                                if new_coloring[x] == c:
                                    new_coloring[x] = target_color
                                elif new_coloring[x] == target_color:
                                    new_coloring[x] = c
                            moved = True
                            break
                if moved:
                    # after moving v, we break and restart? or continue to next vertex?
                    # We'll continue to see if we can move more vertices, but for simplicity, break and try again from start?
                    # We'll just break and try to reduce again in a loop outside? 
                    # For now, we break and return the new coloring, and the outer loop will try again.
                    break
        # If we changed something, check validity and return
        if is_valid(new_coloring):
            return new_coloring
        return coloring

    # Apply Kempe reduction iteratively (up to 3 times) to try to reduce color count
    current = best_coloring
    for _ in range(3):
        k_before = num_colors(current)
        reduced = kempe_reduce(current)
        k_after = num_colors(reduced)
        if k_after < k_before:
            current = reduced
        else:
            break

    return current

