def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for row in adj:
            if len(row) != len(adj):
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor sets for efficient access
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].add(j)

    # Helper: DSATUR with tie-breaking by degree in uncolored subgraph
    def dsatur():
        color = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color sets for fast update
        neighbor_colors = [set() for _ in range(n)]
        uncolored = set(range(n))

        # initial ordering by degree descending
        order = sorted(uncolored, key=lambda x: (-len(neighbors[x]), x))
        for v in order:
            if color[v] != -1:
                continue
            # find smallest available color
            used = neighbor_colors[v]
            c = 0
            while c in used:
                c += 1
            color[v] = c
            # update saturation and neighbor colors for uncolored neighbors
            for u in neighbors[v]:
                if color[u] == -1:
                    if c not in neighbor_colors[u]:
                        neighbor_colors[u].add(c)
                        saturation[u] = len(neighbor_colors[u])
            # reorder uncolored by saturation, then degree in uncolored subgraph, then index
            uncolored.remove(v)
            if uncolored:
                order = sorted(uncolored, key=lambda x: (-saturation[x], -len([nb for nb in neighbors[x] if nb in uncolored]), x))
        return color

    # Helper: Recursive Largest First (RLF) independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build maximal independent set S for color c
            S = set()
            # vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (len([nb for nb in neighbors[x] if nb in uncolored]), -x))
            S.add(v)
            # partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if u not in S and not any(nb in S for nb in neighbors[u])}
            W = {u for u in uncolored if u not in S and u not in U}
            # greedily add to S from U
            while U:
                # select u in U with max |N(u) ∩ W|
                u = max(U, key=lambda x: (len([nb for nb in neighbors[x] if nb in W]), -len([nb for nb in neighbors[x] if nb in U]), x))
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for nb in neighbors[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color c to all in S
            for v in S:
                color[v] = c
            # remove S from uncolored
            uncolored -= S
            c += 1
        return color

    # Helper: Welsh-Powell (degree ordering + First-Fit)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: (-len(neighbors[x]), x))
        color = [-1] * n
        for v in order:
            used = {color[u] for u in neighbors[v] if color[u] != -1}
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color

    # Helper: Smallest-Last ordering (degeneracy) + First-Fit
    def smallest_last():
        # core decomposition to get degeneracy ordering
        deg = [len(neighbors[i]) for i in range(n)]
        bin_ = [[] for _ in range(n)]
        pos = list(range(n))
        for v in range(n):
            d = deg[v]
            if d < n:
                bin_[d].append(v)
        # reconstruct ordering
        order = []
        current = 0
        for i in range(n):
            while not bin_[current]:
                current += 1
            v = bin_[current].pop()
            order.append(v)
            for u in neighbors[v]:
                if deg[u] > current:
                    # move u from bin[deg[u]] to bin[deg[u]-1]
                    d = deg[u]
                    bin_[d].remove(u)
                    deg[u] -= 1
                    bin_[deg[u]].append(u)
                    if deg[u] < current:
                        current = deg[u]
        # color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = {color[u] for u in neighbors[v] if color[u] != -1}
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color

    # Helper: Kempe chain local search to reduce colors
    def kempe_reduce(color_in):
        color = color_in[:]
        k = max(color) + 1 if n > 0 else 0
        improved = True
        while improved and k > 1:
            improved = False
            # target: eliminate color k-1
            target = k - 1
            vertices = [v for v in range(n) if color[v] == target]
            random.shuffle(vertices)  # randomize order to avoid bias
            for v in vertices:
                # try to move v to a lower color directly
                neighbor_colors = {color[u] for u in neighbors[v] if color[u] != -1}
                for c in range(target):
                    if c not in neighbor_colors:
                        color[v] = c
                        improved = True
                        break
                if improved:
                    break
                # try Kempe chains for each lower color
                for c in range(target):
                    if c in {color[u] for u in neighbors[v]}:
                        continue  # adjacent, swap would cause conflict
                    # find Kempe chain (c, target) containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if color[node] == c or color[node] == target:
                            component.add(node)
                            for nb in neighbors[node]:
                                if color[nb] == c or color[nb] == target:
                                    if nb not in visited:
                                        stack.append(nb)
                    # check if swapping component frees color c for v without pulling others into target
                    # after swap, v would become c, and any vertex in component colored target would become c
                    # we need to ensure no neighbor of any vertex in component (that becomes c) is colored c
                    safe = True
                    for node in component:
                        if color[node] == target:  # will become c
                            for nb in neighbors[node]:
                                if color[nb] == c:  # conflict after swap
                                    safe = False
                                    break
                            if not safe:
                                break
                    if safe:
                        # perform swap
                        for node in component:
                            if color[node] == c:
                                color[node] = target
                            else:  # color[node] == target
                                color[node] = c
                        improved = True
                        break
                if improved:
                    break
            if not improved:
                break
            # if color k-1 is unused, reduce k
            if target not in color:
                k -= 1
        # recompute k after reduction
        k = max(color) + 1 if n > 0 else 0
        return color

    # Run all algorithms and collect candidates
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(welsh_powell())
    candidates.append(smallest_last())

    # Apply Kempe reduction to each candidate
    reduced = []
    for cand in candidates:
        reduced.append(kempe_reduce(cand))

    # Also try Kempe on the best so far iteratively
    best = min(reduced, key=lambda x: (max(x) + 1 if n > 0 else 0, x))
    for _ in range(2):  # a few iterations of Kempe on best
        best = kempe_reduce(best)

    candidates.append(best)

    # Select the candidate with the fewest colors
    best_coloring = min(candidates, key=lambda x: (max(x) + 1 if n > 0 else 0, x))
    return best_coloring

