                nb = neighbors[best_u] & U
                U -= nb
                W |= nb
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Helper: Welsh-Powell ordering
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        return greedy_color(order)

    # Helper: Smallest-Last ordering
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        order = []
        deg = [len(neighbors[i]) for i in range(n)]
        while remaining:
            # Find vertex with min degree in remaining
            v = min(remaining, key=lambda x: deg[x])
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    deg[u] -= 1
        # Color in reverse order
        return greedy_color(order[::-1])

    # Helper: Kempe chain swap to eliminate a color
    def kempe_reduce(coloring):
        # Find max color used
        max_color = max(coloring) if n > 0 else -1
        if max_color < 0:
            return coloring
        # Try to eliminate color classes from high to low
        for target_color in range(max_color, 0, -1):
            # Get vertices with target_color
            verts = [v for v in range(n) if coloring[v] == target_color]
            if not verts:
                continue
            # Try to recolor each vertex
            changed = True
            while changed and verts:
                changed = False
                v = verts.pop()
                # Try direct move to lower color
                neighbor_colors = set(coloring[u] for u in neighbors[v])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    continue
                # Try Kempe chains
                for c in range(target_color):
                    if c in neighbor_colors:
                        continue
                    # Check if v is connected to any c-colored vertex via (target_color, c) Kempe chain
                    # BFS to find the Kempe chain component of v in colors {target_color, c}
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    component = set()
                    while queue:
                        x = queue.popleft()
                        component.add(x)
                        for y in neighbors[x]:
                            if y not in visited and (coloring[y] == target_color or coloring[y] == c):
                                visited.add(y)
                                queue.append(y)
                    # Check if any neighbor of v with color c is NOT in this component
                    has_external = False
                    for u in neighbors[v]:
                        if coloring[u] == c and u not in component:
                            has_external = True
                            break
                    if has_external:
                        # Swap colors in component
                        for x in component:
                            if coloring[x] == target_color:
                                coloring[x] = c
                            else:
                                coloring[x] = target_color
                        changed = True
                        break
                if changed:
                    # After change, restart checking this color class
                    verts = [v2 for v2 in range(n) if coloring[v2] == target_color]
            if not any(coloring[v] == target_color for v in range(n)):
                # Color class eliminated, continue to next lower
                continue
            else:
                # Could not eliminate this color, stop reduction
                break
        return coloring

    # Generate initial colorings
    colorings = []
    colorings.append(dsatur())
    colorings.append(rlf())
    colorings.append(welsh_powell())
    colorings.append(smallest_last())

    # Apply Kempe reduction to each
    reduced = []
    for col in colorings:
        reduced.append(kempe_reduce(col[:]))

    # Select the coloring with the fewest colors
    best = min(reduced, key=lambda x: max(x) + 1 if n > 0 else 0)
    return best

