    # Determine if adj is adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor sets for efficient access
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            for j in adj[i]:
                neighbors[i].add(j)

    # Trivial cases
    if n == 1:
        return [0]

    # Check if graph is complete
    is_complete = True
    for i in range(n):
        if len(neighbors[i]) != n - 1:
            is_complete = False
            break
    if is_complete:
        return list(range(n))

    # Check if graph is edgeless
    has_edge = any(len(neighbors[i]) > 0 for i in range(n))
    if not has_edge:
        return [0] * n

    # DSATUR algorithm
    color = [-1] * n
    saturation = [0] * n  # saturation degree (number of distinct colors in neighbors)
    # neighbor_colors[v] is a set of colors used by colored neighbors of v
    neighbor_colors = [set() for _ in range(n)]
    uncolored = set(range(n))

    # Helper function to compute degree in uncolored subgraph
    def deg_uncolored(v):
        return sum(1 for u in neighbors[v] if u in uncolored)

    # Main coloring loop
    while uncolored:
        # Select vertex with maximum saturation degree
        max_sat = -1
        candidates = []
        for v in uncolored:
            if saturation[v] > max_sat:
                max_sat = saturation[v]
                candidates = [v]
            elif saturation[v] == max_sat:
                candidates.append(v)

        # Tie-break by maximum degree in uncolored subgraph
        if len(candidates) > 1:
            max_deg = -1
            new_candidates = []
            for v in candidates:
                d = deg_uncolored(v)
                if d > max_deg:
                    max_deg = d
                    new_candidates = [v]
                elif d == max_deg:
                    new_candidates.append(v)
            candidates = new_candidates

        # Final tie-break: random choice
        v = random.choice(candidates)

        # Find smallest available color (mex)
        used = neighbor_colors[v]
        c = 0
        while c in used:
            c += 1
        color[v] = c
        uncolored.remove(v)

        # Update saturation and neighbor_colors for uncolored neighbors
        for u in neighbors[v]:
            if u in uncolored:
                if c not in neighbor_colors[u]:
                    neighbor_colors[u].add(c)
                    saturation[u] += 1

    # Kempe chain refinement to minimize color count
    max_color = max(color) if n > 0 else -1
    if max_color < 0:
        return color

    # Try to reduce colors from highest downwards
    for k in range(max_color, 0, -1):
        # Get vertices with color k
        vertices_k = [i for i in range(n) if color[i] == k]
        if not vertices_k:
            continue  # This color is already unused

        # Try to recolor each vertex in color k to a lower color
        success = True
        for v in vertices_k:
            # Find forbidden colors from neighbors
            forbidden = set()
            for u in neighbors[v]:
                forbidden.add(color[u])

            # Try to find an available color < k
            found = False
            for c in range(k):
                if c not in forbidden:
                    color[v] = c
                    found = True
                    break
            if found:
                continue

            # Try Kempe chain swaps for each color c < k
            swapped = False
            for c in range(k):
                # If v already has color c (shouldn't happen as we checked forbidden), skip
                if color[v] == c:
                    swapped = True
                    break
                # We'll try to swap colors c and k in the component containing v
                # Only consider vertices with color c or k
                stack = [v]
                visited = set()
                component = set()
                has_c = False  # whether the component has a vertex of color c
                while stack:
                    node = stack.pop()
                    if node in visited:
                        continue
                    visited.add(node)
                    component.add(node)
                    if color[node] == c:
                        has_c = True
                    # Explore neighbors with color c or k
                    for u in neighbors[node]:
                        if color[u] == c or color[u] == k:
                            if u not in visited:
                                stack.append(u)
                # If the component does not contain color c, we can swap
                if not has_c:
                    # Swap colors c and k in the component
                    for node in component:
                        if color[node] == c:
                            color[node] = k
                        elif color[node] == k:
                            color[node] = c
                    swapped = True
                    break
            if not swapped:
                success = False
                break

        if success:
            # All vertices of color k were recolored, so we can reduce max color
            # Actually, we just cleared color k, so max color decreases by at least 1
            # But we continue to try lower k in the loop
            pass
        else:
            # Could not eliminate color k, so break
            break

    return color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if it's a binary matrix
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            if is_matrix:
                for val in adj[i]:
                    if val not in (0, 1):
                        is_matrix = False
                        break
            if not is_matrix:
                break

    # Build adjacency list and degree list
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            row = adj[i]
            for j in range(n):
                if row[j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj

    degrees = [len(adj_list[i]) for i in range(n)]

    # Helper: get uncolored neighbors count for a vertex
    def uncolored_neighbors_count(v, colored):
        cnt = 0
        for u in adj_list[v]:
            if not colored[u]:
                cnt += 1
        return cnt

    # Helper: get saturation degree (number of distinct colors in colored neighbors)
    def saturation_degree(v, colored, colors):
        neighbor_colors = set()
        for u in adj_list[v]:
            if colored[u]:
                neighbor_colors.add(colors[u])
        return len(neighbor_colors)

    # Helper: check if assigning color c to vertex v is valid
    def is_valid_color(v, c, colored, colors):
        for u in adj_list[v]:
            if colored[u] and colors[u] == c:
                return False
        return True

    # DSATUR algorithm
    def dsatur():
        colored = [False] * n
        colors = [-1] * n
        # Initial vertex: choose one with highest degree
        v = max(range(n), key=lambda x: degrees[x])
        colors[v] = 0
        colored[v] = True
        colored_count = 1

        while colored_count < n:
            # Select uncolored vertex with max saturation degree
            max_sat = -1
            candidates = []
            for v in range(n):
                if not colored[v]:
                    sat = saturation_degree(v, colored, colors)
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [v]
                    elif sat == max_sat:
                        candidates.append(v)
            # Tie-break: max degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                final_candidates = []
                for v in candidates:
                    deg = uncolored_neighbors_count(v, colored)
                    if deg > max_deg:
                        max_deg = deg
                        final_candidates = [v]
                    elif deg == max_deg:
                        final_candidates.append(v)
                candidates = final_candidates
            # Final tie-break: random
            v = random.choice(candidates) if candidates else 0

            # Assign smallest available color
            used = [False] * (n + 1)  # n colors are enough
            for u in adj_list[v]:
                if colored[u]:
                    c = colors[u]
                    if c <= n:
                        used[c] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            colors[v] = c
            colored[v] = True
            colored_count += 1

        return colors, max(colors) + 1 if n > 0 else 0

    # RLF algorithm (Largest First Independent Set)
    def rlf():
        colored = [False] * n
        colors = [-1] * n
        color_count = 0
        # Set of uncolored vertices
        R = set(range(n))

        while R:
            # Build maximal independent set S for current color
            S = []
            # Step 1: choose vertex with max degree in G[R]
            if R:
                v = max(R, key=lambda x: sum(1 for u in adj_list[x] if u in R))
                S.append(v)
                # Partition R \ {v} into U and W
                U = set()
                W = set()
                for u in R:
                    if u == v:
                        continue
                    # Check if u is adjacent to any in S
                    adjacent = False
                    for s in S:
                        if u in adj_list[s]:
                            adjacent = True
                            break
                    if adjacent:
                        W.add(u)
                    else:
                        U.add(u)
                # Step 4: while U not empty
                while U:
                    # Select u in U with max |N(u) ∩ W|
                    best_u = None
                    max_w_neighbors = -1
                    min_deg_in_U = float('inf')
                    for u in U:
                        # Count neighbors in W
                        w_neighbors = 0
                        for nb in adj_list[u]:
                            if nb in W:
                                w_neighbors += 1
                        # Tie-break: min degree in G[U]
                        deg_in_U = sum(1 for nb in adj_list[u] if nb in U)
                        if w_neighbors > max_w_neighbors or \
                           (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U):
                            max_w_neighbors = w_neighbors
                            min_deg_in_U = deg_in_U
                            best_u = u
                    if best_u is None:
                        break  # Should not happen
                    # Add best_u to S
                    S.append(best_u)
                    U.remove(best_u)
                    # Move neighbors of best_u in U to W
                    for nb in adj_list[best_u]:
                        if nb in U:
                            U.remove(nb)
                            W.add(nb)
                # Assign color to all in S
                for v in S:
                    colors[v] = color_count
                    colored[v] = True
                # Remove S from R
                R -= set(S)
                color_count += 1

        return colors, color_count

    # Smallest-Last ordering (Matula & Beck) with First-Fit
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [degrees[i] for i in range(n)]
        order = []
        # We'll maintain a list of vertices by current degree
        buckets = [[] for _ in range(n)]  # max degree is n-1
        for v in range(n):
            d = degree[v]
            if d < n:
                buckets[d].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # Find non-empty bucket
            while ptr < n and not buckets[ptr]:
                ptr += 1
            if ptr >= n:
                break  # should not happen
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            # Remove v
            remaining.remove(v)
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d_u = degree[u]
                    # Remove u from its current bucket
                    if d_u < n and u in buckets[d_u]:
                        buckets[d_u].remove(u)
                    degree[u] -= 1
                    d_u_new = degree[u]
                    if d_u_new < n:
                        buckets[d_u_new].append(u)
            # Adjust ptr if needed
            if ptr > 0:
                ptr = 0
        # Now color in reverse order
        colored = [False] * n
        colors = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)
            for u in adj_list[v]:
                if colored[u]:
                    c = colors[u]
                    if c <= n:
                        used[c] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            colors[v] = c
            colored[v] = True
        return colors, max(colors) + 1 if n > 0 else 0

    # Welsh-Powell ordering (sort by degree descending) with First-Fit
    def welsh_powell():
        # Order by degree non-increasing
        order = sorted(range(n), key=lambda x: degrees[x], reverse=True)
        colored = [False] * n
        colors = [-1] * n
        for v in order:
            used = [False] * (n + 1)
            for u in adj_list[v]:
                if colored[u]:
                    c = colors[u]
                    if c <= n:
                        used[c] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            colors[v] = c
            colored[v] = True
        return colors, max(colors) + 1 if n > 0 else 0

    # Kempe chain color class elimination local search
    def kempe_local_search(initial_colors, initial_k):
        # Make a copy
        colors = initial_colors[:]
        k = initial_k
        improved = True
        # We'll try to eliminate the last color class repeatedly
        while improved and k > 0:
            improved = False
            # Find vertices with color k-1
            last_color = k - 1
            vertices_last = [v for v in range(n) if colors[v] == last_color]
            if not vertices_last:
                # No vertices with this color, reduce k
                k -= 1
                improved = True
                continue
            # Try to recolor each vertex in last color class
            for v in vertices_last:
                # Try to move v to a lower color directly
                moved = False
                for c in range(last_color):
                    # Check if color c is available
                    conflict = False
                    for u in adj_list[v]:
                        if colors[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        colors[v] = c
                        moved = True
                        improved = True
                        break
                if moved:
                    continue
                # Try Kempe chains with each lower color
                for c in range(last_color):
                    # We want to see if we can swap colors in a (last_color, c) Kempe chain
                    # containing v to free color c for v.
                    # Build the Kempe chain component of v in colors {c, last_color}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    has_c = False  # whether the component contains color c
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        if colors[x] == c:
                            has_c = True
                        for nb in adj_list[x]:
                            if not visited[nb] and (colors[nb] == c or colors[nb] == last_color):
                                visited[nb] = True
                                queue.append(nb)
                    # If the component does not contain color c, we can swap
                    if not has_c:
                        # Swap colors c and last_color in the component
                        for x in component:
                            if colors[x] == last_color:
                                colors[x] = c
                            elif colors[x] == c:
                                colors[x] = last_color
                        # Now v has color c (since it was last_color and we swapped)
                        improved = True
                        break  # break from color loop
                if improved:
                    break  # break from vertex loop
            # After attempting to recolor all vertices in last color class,
            # check if any vertex still has color last_color
            if not any(colors[v] == last_color for v in range(n)):
                k -= 1
                improved = True  # to continue trying to reduce further
        return colors, k

    # Run all algorithms and collect results
    algorithms = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Smallest-Last", smallest_last),
        ("Welsh-Powell", welsh_powell)
    ]

    best_colors = None
    best_k = float('inf')

    for name, alg in algorithms:
        try:
            cols, k = alg()
            # Validate coloring
            valid = True
            for u in range(n):
                for v in adj_list[u]:
                    if u < v and colors[u] == colors[v]:  # check each edge once
                        valid = False
                        break
                if not valid:
                    break
            if valid and k < best_k:
                best_k = k
                best_colors = cols[:]
        except Exception:
            continue

    # If no algorithm produced a valid coloring (should not happen), fallback to greedy
    if best_colors is None:
        # Simple greedy: order by degree descending
        order = sorted(range(n), key=lambda x: degrees[x], reverse=True)
        colors = [-1] * n
        for v in order:
            used = [False] * (n + 1)
            for u in adj_list[v]:
                if colors[u] != -1:
                    c = colors[u]
                    if c <= n:
                        used[c] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            colors[v] = c
        best_colors = colors
        best_k = max(colors) + 1 if n > 0 else 0

    # Apply Kempe chain local search to try to improve
    try:
        improved_colors, improved_k = kempe_local_search(best_colors, best_k)
        # Validate
        valid = True
        for u in range(n):
            for v in adj_list[u]:
                if u < v and improved_colors[u] == improved_colors[v]:
                    valid = False
                    break
            if not valid:
                break
        if valid and improved_k < best_k:
            best_colors = improved_colors
            best_k = improved_k
    except Exception:
        pass

    return best_colors

