            if not uncolored:
                break
            v = max(uncolored, key=lambda x: sum(1 for u in neighbors[x] if u in uncolored))
            S.append(v)
            # Partition U and W
            U = uncolored - {v}
            W = set()
            for u in neighbors[v]:
                if u in U:
                    U.remove(u)
                    W.add(u)
            # Step 4: while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                def select_u(u):
                    # |N(u) ∩ W|
                    w_count = 0
                    for w in neighbors[u]:
                        if w in W:
                            w_count += 1
                    # degree in G[U]
                    deg_u = 0
                    for w in neighbors[u]:
                        if w in U:
                            deg_u += 1
                    return (-w_count, deg_u, random.random())
                u = min(U, key=select_u)
                S.append(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to S
            for v in S:
                color[v] = current_color
            uncolored -= set(S)
            current_color += 1
        return color

    # Smallest-Last ordering
    def smallest_last():
        # core decomposition to get degeneracy ordering
        degree_copy = degree[:]
        # bin vertices by degree
        max_deg = max(degree) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree_copy[v]
            bins[d].append(v)
        # pointer to current non-empty bin
        pos = 0
        order = []
        # we'll maintain a list of vertices and update degrees
        # using the standard algorithm
        # Actually, we can use the simple peel-min-degree
        # Since n <= 100, we can do O(n^2)
        remaining = set(range(n))
        deg = degree_copy[:]
        stack = []
        while remaining:
            # find vertex with min degree in remaining
            v = min(remaining, key=lambda x: deg[x])
            stack.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    deg[u] -= 1
        # reverse stack for coloring order
        order = stack[::-1]
        return greedy_color(order)

    # Welsh-Powell ordering
    def welsh_powell():
        order = sorted(range(n), key=lambda x: (-degree[x], x))
        return greedy_color(order)

    # Try multiple orderings and pick the best
    colorings = []
    # DSATUR
    colorings.append(dsatur())
    # RLF
    colorings.append(rlf())
    # Smallest-Last
    colorings.append(smallest_last())
    # Welsh-Powell
    colorings.append(welsh_powell())
    # Also try greedy on random orders a few times
    for _ in range(10):
        order = list(range(n))
        random.shuffle(order)
        colorings.append(greedy_color(order))

    # Select the coloring with the minimum number of colors
    best_color = None
    best_k = float('inf')
    for c in colorings:
        k = max(c) + 1 if c else 0
        if k < best_k:
            best_k = k
            best_color = c
    return best_color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    # Detect adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for i in range(n):
            if len(adj[i]) != n:
                all_binary = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True
    # Build neighbor list
    if is_matrix:
        neighbors = []
        for i in range(n):
            row = adj[i]
            nbrs = [j for j in range(n) if row[j] == 1 and j != i]
            neighbors.append(nbrs)
    else:
        neighbors = []
        for i in range(n):
            if isinstance(adj[i], list):
                nbrs = [v for v in adj[i] if 0 <= v < n and v != i]
                neighbors.append(nbrs)
            else:
                neighbors.append([])
    # Helper: DSATUR coloring
    def dsatur_coloring():
        color = [-1] * n
        saturation = [0] * n
        uncolored = set(range(n))
        # Initial vertex: max degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(neighbors[x]))
            color[v] = 0
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    saturation[u] += 1
        while uncolored:
            # Find vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            max_sat = -1
            candidates = []
            for v in uncolored:
                sat_v = saturation[v]
                if sat_v > max_sat:
                    max_sat = sat_v
                    candidates = [v]
                elif sat_v == max_sat:
                    candidates.append(v)
            if max_sat == -1:
                # All saturation 0, pick max degree in uncolored subgraph
                v = max(uncolored, key=lambda x: len([u for u in neighbors[x] if u in uncolored]))
            else:
                # Tie-break by degree in uncolored subgraph
                max_deg = -1
                best_candidates = []
                for v in candidates:
                    deg = len([u for u in neighbors[v] if u in uncolored])
                    if deg > max_deg:
                        max_deg = deg
                        best_candidates = [v]
                    elif deg == max_deg:
                        best_candidates.append(v)
                v = random.choice(best_candidates)
            # Assign smallest available color
            used = [False] * (n + 1)
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used[c] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    # Check if color c is new to u's neighborhood
                    new = True
                    for w in neighbors[u]:
                        if w != v and color[w] == c and w in uncolored:
                            new = False
                            break
                    if new:
                        saturation[u] += 1
        return color
    # Helper: RLF coloring
    def rlf_coloring():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0
        while uncolored:
            # Build maximal independent set S for current_color
            S = []
            # Step 1: pick vertex with max degree in G[uncolored]
            if uncolored:
                v = max(uncolored, key=lambda x: len([u for u in neighbors[x] if u in uncolored]))
                S.append(v)
                # Partition U and W
                U = set(uncolored) - {v}
                W = set()
                for u in neighbors[v]:
                    if u in U:
                        U.remove(u)
                        W.add(u)
                # Step 2: while U not empty
                while U:
                    # Select u in U with max |N(u) ∩ W|
                    best_u = None
                    max_common = -1
                    for u in U:
                        common = 0
                        for w in neighbors[u]:
                            if w in W:
                                common += 1
                        if common > max_common:
                            max_common = common
                            best_u = u
                        elif common == max_common:
                            # Tie-break: min degree in G[U]
                            deg_u = len([x for x in neighbors[u] if x in U])
                            deg_best = len([x for x in neighbors[best_u] if x in U]) if best_u is not None else -1
                            if deg_u < deg_best:
                                best_u = u
                    if best_u is None:
                        # Should not happen, but break
                        break
                    S.append(best_u)
                    U.remove(best_u)
                    # Move neighbors of best_u from U to W
                    for w in neighbors[best_u]:
                        if w in U:
                            U.remove(w)
                            W.add(w)
                # Assign color to S
                for vertex in S:
                    color[vertex] = current_color
                uncolored -= set(S)
                current_color += 1
        return color
    # Helper: degeneracy ordering (smallest-last)
    def degeneracy_ordering():
        if n == 0:
            return []
        # Compute degrees and adjacency sets for fast lookup
        degree = [len(neighbors[i]) for i in range(n)]
        adj_set = [set(neighbors[i]) for i in range(n)]
        # Buckets for degrees
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            d = degree[i]
            buckets[d].append(i)
        # Track position in bucket
        pos_in_bucket = [0] * n
        for i in range(n):
            d = degree[i]
            pos_in_bucket[i] = len(buckets[d]) - 1  # will be updated when removed
        # Actually, we'll maintain buckets as lists and remove by swapping
        # Reinitialize buckets as lists of vertices
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[degree[i]].append(i)
        # Pointers to current position in bucket for O(1) removal
        bucket_pos = [0] * n
        for d in range(max_deg + 1):
            for idx, v in enumerate(buckets[d]):
                bucket_pos[v] = idx
        # Core decomposition
        deleted = [False] * n
        order = []
        # Current min degree
        min_deg = 0
        for _ in range(n):
            # Find non-empty bucket from min_deg upwards
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            deleted[v] = True
            order.append(v)
            # Update bucket_pos: last element moved to position of v if any
            if buckets[min_deg]:
                last = buckets[min_deg][-1]
                bucket_pos[last] = bucket_pos[v]
            # Update neighbors
            for u in neighbors[v]:
                if not deleted[u]:
                    d_u = degree[u]
                    # Remove u from bucket d_u
                    pos_u = bucket_pos[u]
                    # Swap with last in bucket d_u
                    last_u = buckets[d_u][-1]
                    buckets[d_u][pos_u] = last_u
                    bucket_pos[last_u] = pos_u
                    buckets[d_u].pop()
                    # Decrease degree
                    degree[u] -= 1
                    d_new = degree[u]
                    buckets[d_new].append(u)
                    bucket_pos[u] = len(buckets[d_new]) - 1
                    # Update min_deg if necessary
                    if d_new < min_deg:
                        min_deg = d_new
        # Reverse order for coloring
        return order[::-1]
    # Helper: greedy coloring with given order
    def greedy_coloring(order):
        color = [-1] * n
        for v in order:
            used = [False] * (n + 1)
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used[c] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            color[v] = c
        return color
    # Helper: Kempe chain swap
    def kempe_swap(color, a, b, v):
        # Returns new color array if swap in component of v (color a) with b is possible and beneficial, else None
        # We will try to move v from color a to color b by swapping in the (a,b)-Kempe chain
        # Only if v is color a
        if color[v] != a:
            return None
        # Find the Kempe chain component of v in colors a and b
        stack = [v]
        visited = set([v])
        comp_a = set()  # vertices in component with color a
        comp_b = set()  # vertices in component with color b
        while stack:
            node = stack.pop()
            if color[node] == a:
                comp_a.add(node)
            elif color[node] == b:
                comp_b.add(node)
            for u in neighbors[node]:
                if u not in visited and (color[u] == a or color[u] == b):
                    visited.add(u)
                    stack.append(u)
        # Check if any vertex in comp_b has a neighbor with color a outside the component? Actually, swapping is always valid.
        # But we want to free color a for v? Actually, after swap, v will become color b.
        # We want to see if we can recolor v to some color < a? Actually, we are trying to eliminate color class a.
        # In the context of color class elimination, we try to move a vertex of color a to color b via Kempe chain.
        # After swap, the vertex v will have color b.
        # We return the new coloring after swap.
        new_color = color[:]
        for node in comp_a:
            new_color[node] = b
        for node in comp_b:
            new_color[node] = a
        return new_color
    # Helper: try to reduce number of colors using Kempe chains
    def reduce_colors_kempe(color):
        # Determine number of colors used
        max_color = max(color) if n > 0 else -1
        if max_color < 0:
            return color
        # Try to eliminate color classes from highest down
        for target_color in range(max_color, 0, -1):
            # Collect vertices with color target_color
            vertices_target = [i for i in range(n) if color[i] == target_color]
            if not vertices_target:
                continue
            # Try to recolor each vertex in vertices_target to a lower color
            made_change = False
            for v in vertices_target:
                # Try direct move to lower color
                for c in range(target_color):
                    conflict = False
                    for u in neighbors[v]:
                        if color[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        # Recolor v to c
                        color[v] = c
                        made_change = True
                        break
                if made_change:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Try to swap in (c, target_color) chain to free color c for v
                    # Only if v is in color target_color
                    if color[v] != target_color:
                        continue
                    new_col = kempe_swap(color, target_color, c, v)
                    if new_col is not None:
                        # After swap, check if v now has color c (it should)
                        if new_col[v] == c:
                            color[:] = new_col
                            made_change = True
                            break
                if made_change:
                    break
            if not made_change:
                # Could not eliminate this color class, move to next lower
                continue
            else:
                # After change, restart from highest color again
                return reduce_colors_kempe(color)
        return color
    # Main: try multiple heuristics and pick best
    best_coloring = None
    best_num_colors = float('inf')
    # List of coloring functions to try
    coloring_funcs = [
        dsatur_coloring,
        rlf_coloring,
        lambda: greedy_coloring(degeneracy_ordering()),
        lambda: greedy_coloring(sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)),
        lambda: greedy_coloring(list(range(n))),
    ]
    for func in coloring_funcs:
        try:
            col = func()
            # Validate coloring
            valid = True
            for i in range(n):
                for j in neighbors[i]:
                    if i < j and col[i] == col[j]:
                        valid = False
                        break
                if not valid:
                    break
            if not valid:
                continue
            num_colors = len(set(col)) if n > 0 else 0
            if num_colors < best_num_colors:
                best_num_colors = num_colors
                best_coloring = col[:]
                if best_num_colors == 1:  # optimal possible
                    break
        except Exception:
            continue
    # If no valid coloring found (should not happen), fallback to greedy
    if best_coloring is None:
        best_coloring = greedy_coloring(list(range(n)))
    # Apply Kempe chain reduction to try to improve
    best_coloring = reduce_colors_kempe(best_coloring)
    return best_coloring
